# miss_handler_arb

```systemverilog
// =============================================================================
// miss_handler_arb -- d_ca05 : multi-requester cache miss handler
// -----------------------------------------------------------------------------
// Architecture: a single-MSHR FSM. Work is taken in the priority order
//   refill miss  >  bypass access  >  pending/taken atomic  >  flush,
// which realises F9 ("atomics are the lowest priority work this unit does").
//
// Clause map:
//   F2  bypass/refill arbitration is a strict lowest-index priority encoder.
//   F3  the MSHR comparators: the index comparison is a sub-range of the
//       address comparison (they assert together), and the served requester
//       is NOT excluded from either output.
//   F4  flush walk: one array read + one all-ways vldrty write per set,
//       ascending, 256 sets -> 512 array accesses of which 256 are writes.
//   F5/F7/F8  flush acknowledgement is gated by flush_ack_en, which is set
//       when the walk starts: 1 only for a flush requested by flush_i with
//       no coincident atomic request.  A flush_i && amo_req_i.req in the same
//       cycle therefore runs the full walk with no acknowledgement ever.
//   F6/F9  an atomic forces the walk first, is latched at take-time, and its
//       pending state is cleared whenever a refill miss is served instead.
//   A7  the AMO is an ATOP write on the bypass port; both B and R are consumed
//       and the R payload becomes amo_resp_o.result.
// =============================================================================
module miss_handler_arb
  import miss_handler_arb_pkg::*;
#(
    parameter int unsigned NR_PORTS = 4     // scored at 4; see P2
) (
    input  logic clk,
    input  logic rst_n,                     // active low, asynchronous assert

    input  logic flush_i,
    output logic flush_ack_o,
    output logic miss_o,
    input  logic busy_i,

    input  logic [NR_PORTS-1:0][$bits(miss_req_t)-1:0] miss_req_i,
    output logic [NR_PORTS-1:0]       bypass_gnt_o,
    output logic [NR_PORTS-1:0]       bypass_valid_o,
    output logic [NR_PORTS-1:0][63:0] bypass_data_o,
    output logic [NR_PORTS-1:0]       miss_gnt_o,
    output logic [NR_PORTS-1:0]       active_serving_o,
    output logic [63:0]               critical_word_o,
    output logic                      critical_word_valid_o,

    input  logic [NR_PORTS-1:0][55:0] mshr_addr_i,
    output logic [NR_PORTS-1:0]       mshr_addr_matches_o,
    output logic [NR_PORTS-1:0]       mshr_index_matches_o,

    input  amo_req_t  amo_req_i,
    output amo_resp_t amo_resp_o,

    output axi_req_t axi_bypass_req_o,
    input  axi_rsp_t axi_bypass_rsp_i,

    output axi_req_t axi_data_req_o,
    input  axi_rsp_t axi_data_rsp_i,

    output logic [SET_ASSOC-1:0]        req_o,
    output logic [INDEX_WIDTH-1:0]      addr_o,
    output cache_line_t                 data_o,
    output cl_be_t                      be_o,
    input  cache_line_t [SET_ASSOC-1:0] data_i,
    output logic                        we_o
);

  // ---------------------------------------------------------------------------
  // local geometry (P1/P2)
  // ---------------------------------------------------------------------------
  localparam int unsigned BEATS     = LINE_WIDTH / AXI_DATA_W;        // 2
  localparam int unsigned BEAT_W    = (BEATS   > 1) ? $clog2(BEATS)     : 1;
  localparam int unsigned PORT_W    = (NR_PORTS > 1) ? $clog2(NR_PORTS) : 1;
  localparam int unsigned AXI_BYTES = AXI_DATA_W / 8;                  // 8

  // ---------------------------------------------------------------------------
  // FSM
  // ---------------------------------------------------------------------------
  typedef enum logic [4:0] {
    IDLE, CHECK, WB_AW, WB_W0, WB_W1, WB_B,
    REFILL_AR, REFILL_R, REFILL_W,
    FLUSH, FLUSH_INV,
    BYPASS_AW, BYPASS_W, BYPASS_B, BYPASS_AR, BYPASS_R,
    AMO_AW, AMO_W, AMO_WAIT, AMO_DONE
  } state_t;

  state_t       state_q, state_d;
  miss_req_t    miss_req_q, miss_req_d;       // latched refill request (the MSHR)
  miss_req_t    bypass_req_q, bypass_req_d;   // latched bypass request
  amo_req_t     amo_req_q, amo_req_d;         // latched atomic
  logic [PORT_W-1:0]  bypass_port_q, bypass_port_d;
  logic               mshr_valid_q, mshr_valid_d;
  logic [7:0]         flush_cnt_q, flush_cnt_d;
  logic               flush_ack_en_q, flush_ack_en_d;  // F5/F7/F8 gate
  logic               amo_pending_q, amo_pending_d;    // F6/F9
  logic [2:0]         victim_way_q, victim_way_d;
  cache_line_t        victim_line_q, victim_line_d;
  logic [LINE_WIDTH-1:0] line_q, line_d;
  logic [BEAT_W-1:0]  beat_cnt_q, beat_cnt_d;
  logic               got_b_q, got_b_d, got_r_q, got_r_d; // A7: need B and R
  logic [63:0]        amo_result_q, amo_result_d;

  // registered output pulses / values
  logic                flush_ack_q, flush_ack_d;
  logic                miss_pulse_q, miss_pulse_d;
  logic                amo_ack_q, amo_ack_d;
  logic [NR_PORTS-1:0] bypass_valid_q, bypass_valid_d;
  logic [63:0]         bypass_data_q, bypass_data_d;
  logic [NR_PORTS-1:0] active_serving_q, active_serving_d;

  // ---------------------------------------------------------------------------
  // unpack the packed request vector into structs
  // ---------------------------------------------------------------------------
  miss_req_t req [NR_PORTS];
  always_comb begin : p_unpack
    for (int i = 0; i < NR_PORTS; i++)
      req[i] = miss_req_t'(miss_req_i[i]);
  end

  // ---------------------------------------------------------------------------
  // arbitration: strict lowest-index priority, starving (F2)
  // ---------------------------------------------------------------------------
  logic miss_sel_valid, bypass_sel_valid;
  logic [PORT_W-1:0] miss_sel, bypass_sel;
  always_comb begin : p_arb
    miss_sel       = '0;
    miss_sel_valid = 1'b0;
    bypass_sel     = '0;
    bypass_sel_valid = 1'b0;
    // downward iteration: the lowest index is assigned last and wins
    for (int i = NR_PORTS-1; i >= 0; i--) begin
      if (req[i].valid && !req[i].bypass) begin
        miss_sel       = PORT_W'(i);
        miss_sel_valid = 1'b1;
      end
      if (req[i].valid && req[i].bypass) begin
        bypass_sel       = PORT_W'(i);
        bypass_sel_valid = 1'b1;
      end
    end
  end

  // ---------------------------------------------------------------------------
  // victim way: first invalid way, else way 0
  // ---------------------------------------------------------------------------
  logic [2:0]  victim_way;
  cache_line_t victim_line;
  logic        victim_dirty;
  always_comb begin : p_victim
    victim_way = '0;
    for (int i = SET_ASSOC-1; i >= 0; i--)
      if (!data_i[i].valid)
        victim_way = 3'(i);
    victim_line  = data_i[victim_way];
    victim_dirty = victim_line.dirty;
  end

  // ---------------------------------------------------------------------------
  // store-merge into the refilled line (store misses allocate dirty)
  // ---------------------------------------------------------------------------
  logic [63:0]     store_word_off;
  logic [LINE_WIDTH-1:0] line_merged;
  always_comb begin : p_merge
    store_word_off = 64 * miss_req_q.addr[OFFSET_WIDTH-1:3];
    line_merged    = line_q;
    if (miss_req_q.we) begin
      for (int b = 0; b < 8; b++)
        if (miss_req_q.be[b])
          line_merged[store_word_off + 8*b +: 8] = miss_req_q.wdata[8*b +: 8];
    end
  end

  // ---------------------------------------------------------------------------
  // AMO write strobes (aligned on operand_a)
  // ---------------------------------------------------------------------------
  logic [AXI_BYTES-1:0] amo_strb;
  always_comb begin : p_amo_strb
    case (amo_req_q.size)
      2'd0:    amo_strb = AXI_BYTES'(8'h01 << amo_req_q.operand_a[2:0]);
      2'd1:    amo_strb = AXI_BYTES'(8'h03 << amo_req_q.operand_a[2:0]);
      2'd2:    amo_strb = AXI_BYTES'(8'h0f << amo_req_q.operand_a[2:0]);
      default: amo_strb = '1;
    endcase
  end

  // ---------------------------------------------------------------------------
  // main FSM
  // ---------------------------------------------------------------------------
  always_comb begin : p_fsm
    // defaults: every register and combinational output gets a value
    state_d          = state_q;
    miss_req_d       = miss_req_q;
    bypass_req_d     = bypass_req_q;
    amo_req_d        = amo_req_q;
    bypass_port_d   = bypass_port_q;
    mshr_valid_d     = mshr_valid_q;
    flush_cnt_d      = flush_cnt_q;
    flush_ack_en_d   = flush_ack_en_q;
    amo_pending_d    = amo_pending_q;
    victim_way_d     = victim_way_q;
    victim_line_d    = victim_line_q;
    line_d           = line_q;
    beat_cnt_d       = beat_cnt_q;
    got_b_d          = got_b_q;
    got_r_d          = got_r_q;
    amo_result_d     = amo_result_q;
    flush_ack_d      = 1'b0;
    miss_pulse_d     = 1'b0;
    amo_ack_d        = 1'b0;
    bypass_valid_d   = '0;
    bypass_data_d    = '0;
    active_serving_d = active_serving_q;

    axi_bypass_req_o = '0;
    axi_data_req_o   = '0;
    req_o            = '0;
    addr_o           = '0;
    data_o           = '0;
    be_o             = '0;
    we_o             = 1'b0;

    case (state_q)

      // ------------------------------------------------------------------
      // IDLE: take work in priority order  miss > bypass > pending AMO >
      // new AMO > flush.  busy_i gates flush and AMO, never misses (A4).
      // ------------------------------------------------------------------
      IDLE: begin
        if (miss_sel_valid) begin
          miss_req_d       = req[miss_sel];
          mshr_valid_d     = 1'b1;
          amo_pending_d    = 1'b0;          // F9: miss preempts a pending atomic
          miss_pulse_d     = 1'b1;
          active_serving_d = '0;
          active_serving_d[miss_sel] = 1'b1;
          // issue the set read of the target set in the accept cycle
          req_o  = '1;
          addr_o = req[miss_sel].addr[INDEX_WIDTH+OFFSET_WIDTH-1:OFFSET_WIDTH];
          state_d = CHECK;
        end else if (bypass_sel_valid) begin
          bypass_req_d   = req[bypass_sel];
          bypass_port_d = bypass_sel;
          miss_pulse_d   = 1'b1;
          state_d = req[bypass_sel].we ? BYPASS_AW : BYPASS_AR;
        end else if (amo_pending_q) begin
          amo_pending_d = 1'b0;
          state_d = AMO_AW;
        end else if (amo_req_i.req && !busy_i) begin
          amo_req_d     = amo_req_i;         // latch the atomic (F6)
          amo_pending_d = 1'b1;
          flush_cnt_d   = '0;
          flush_ack_en_d = 1'b0;             // F7: AMO-induced walk never acks
          state_d = FLUSH;
        end else if (flush_i && !busy_i) begin
          flush_cnt_d    = '0;
          flush_ack_en_d = !amo_req_i.req;   // F5 vs F8
          state_d = FLUSH;
        end
      end

      // ------------------------------------------------------------------
      // refill: victim selection / eviction
      // ------------------------------------------------------------------
      CHECK: begin
        victim_way_d  = victim_way;
        victim_line_d = victim_line;
        state_d = victim_dirty ? WB_AW : REFILL_AR;
      end

      WB_AW: begin
        axi_data_req_o.aw_valid = 1'b1;
        axi_data_req_o.aw.id    = '0;
        axi_data_req_o.aw.addr  = {4'b0, victim_line_q.tag,
                                   miss_req_q.addr[INDEX_WIDTH+OFFSET_WIDTH-1:OFFSET_WIDTH],
                                   {OFFSET_WIDTH{1'b0}}};
        axi_data_req_o.aw.len   = 8'(BEATS-1);
        axi_data_req_o.aw.size  = 3'($clog2(AXI_BYTES));
        axi_data_req_o.aw.burst = 2'b01; // INCR
        if (axi_data_rsp_i.aw_ready) state_d = WB_W0;
      end

      WB_W0: begin
        axi_data_req_o.w_valid = 1'b1;
        axi_data_req_o.w.data  = victim_line_q.data[AXI_DATA_W-1:0];
        axi_data_req_o.w.strb  = '1;
        axi_data_req_o.w.last  = 1'b0;
        if (axi_data_rsp_i.w_ready) state_d = WB_W1;
      end

      WB_W1: begin
        axi_data_req_o.w_valid = 1'b1;
        axi_data_req_o.w.data  = victim_line_q.data[2*AXI_DATA_W-1:AXI_DATA_W];
        axi_data_req_o.w.strb  = '1;
        axi_data_req_o.w.last  = 1'b1;
        if (axi_data_rsp_i.w_ready) state_d = WB_B;
      end

      WB_B: begin
        axi_data_req_o.b_ready = 1'b1;
        if (axi_data_rsp_i.b_valid) state_d = REFILL_AR;
      end

      // ------------------------------------------------------------------
      // refill: line fetch and critical-word forwarding (A3)
      // ------------------------------------------------------------------
      REFILL_AR: begin
        axi_data_req_o.ar_valid = 1'b1;
        axi_data_req_o.ar.id    = '0;
        axi_data_req_o.ar.addr  = {miss_req_q.addr[63:OFFSET_WIDTH], {OFFSET_WIDTH{1'b0}}};
        axi_data_req_o.ar.len   = 8'(BEATS-1);
        axi_data_req_o.ar.size  = 3'($clog2(AXI_BYTES));
        axi_data_req_o.ar.burst = 2'b01; // INCR
        if (axi_data_rsp_i.ar_ready) begin
          line_d     = '0;
          beat_cnt_d = '0;
          state_d = REFILL_R;
        end
      end

      REFILL_R: begin
        axi_data_req_o.r_ready = 1'b1;
        if (axi_data_rsp_i.r_valid) begin
          line_d     = {line_q[LINE_WIDTH-AXI_DATA_W-1:0], axi_data_rsp_i.r.data};
          beat_cnt_d = beat_cnt_q + BEAT_W'(1);
          if (axi_data_rsp_i.r.last) state_d = REFILL_W;
        end
      end

      REFILL_W: begin
        req_o = '0;
        req_o[victim_way_q] = 1'b1;
        addr_o = miss_req_q.addr[INDEX_WIDTH+OFFSET_WIDTH-1:OFFSET_WIDTH];
        we_o   = 1'b1;
        be_o.tag    = '1;
        be_o.data   = '1;
        be_o.vldrty = '0;
        be_o.vldrty[victim_way_q] = 1'b1;
        data_o.tag   = miss_req_q.addr[INDEX_WIDTH+OFFSET_WIDTH +: TAG_WIDTH];
        data_o.data  = line_merged;
        data_o.valid = 1'b1;
        data_o.dirty = miss_req_q.we;     // a store miss allocates the line dirty
        mshr_valid_d  = 1'b0;             // refill retires -> match outputs drop (F3)
        active_serving_d = '0;
        state_d = IDLE;
      end

      // ------------------------------------------------------------------
      // flush walk: one read + one all-ways invalidate write per set (F4)
      // ------------------------------------------------------------------
      FLUSH: begin
        req_o  = '1;
        addr_o = {flush_cnt_q, {OFFSET_WIDTH{1'b0}}};
        state_d = FLUSH_INV;
      end

      FLUSH_INV: begin
        req_o  = '1;
        addr_o = {flush_cnt_q, {OFFSET_WIDTH{1'b0}}};
        we_o   = 1'b1;
        be_o.vldrty = '1;                  // invalidate all ways
        data_o      = '0;                 // valid=0, dirty=0
        if (flush_cnt_q == 8'(NUM_WORDS-1)) begin
          flush_ack_d = flush_ack_en_q;   // F5/F7/F8: pulse only if requested
          state_d = IDLE;
        end else begin
          flush_cnt_d = flush_cnt_q + 8'(1);
          state_d = FLUSH;
        end
      end

      // ------------------------------------------------------------------
      // bypass: single-beat read or write on the bypass AXI port
      // ------------------------------------------------------------------
      BYPASS_AW: begin
        axi_bypass_req_o.aw_valid = 1'b1;
        axi_bypass_req_o.aw.id    = '0;
        axi_bypass_req_o.aw.addr  = bypass_req_q.addr;
        axi_bypass_req_o.aw.len   = '0;
        axi_bypass_req_o.aw.size  = 3'(bypass_req_q.size);
        axi_bypass_req_o.aw.burst = 2'b01;
        if (axi_bypass_rsp_i.aw_ready) state_d = BYPASS_W;
      end

      BYPASS_W: begin
        axi_bypass_req_o.w_valid = 1'b1;
        axi_bypass_req_o.w.data  = bypass_req_q.wdata;
        axi_bypass_req_o.w.strb  = bypass_req_q.be;
        axi_bypass_req_o.w.last  = 1'b1;
        if (axi_bypass_rsp_i.w_ready) state_d = BYPASS_B;
      end

      BYPASS_B: begin
        axi_bypass_req_o.b_ready = 1'b1;
        if (axi_bypass_rsp_i.b_valid) begin
          bypass_valid_d[bypass_port_q] = 1'b1;
          bypass_data_d = '0;             // writes carry no read data
          state_d = IDLE;
        end
      end

      BYPASS_AR: begin
        axi_bypass_req_o.ar_valid = 1'b1;
        axi_bypass_req_o.ar.id    = '0;
        axi_bypass_req_o.ar.addr  = bypass_req_q.addr;
        axi_bypass_req_o.ar.len   = '0;
        axi_bypass_req_o.ar.size  = 3'(bypass_req_q.size);
        axi_bypass_req_o.ar.burst = 2'b01;
        if (axi_bypass_rsp_i.ar_ready) state_d = BYPASS_R;
      end

      BYPASS_R: begin
        axi_bypass_req_o.r_ready = 1'b1;
        if (axi_bypass_rsp_i.r_valid) begin
          bypass_valid_d[bypass_port_q] = 1'b1;
          bypass_data_d = axi_bypass_rsp_i.r.data;
          state_d = IDLE;
        end
      end

      // ------------------------------------------------------------------
      // atomic: ATOP write on the bypass port, consuming BOTH B and R (A7)
      // ------------------------------------------------------------------
      AMO_AW: begin
        axi_bypass_req_o.aw_valid = 1'b1;
        axi_bypass_req_o.aw.id    = '0;
        axi_bypass_req_o.aw.addr  = amo_req_q.operand_a;
        axi_bypass_req_o.aw.len   = '0;
        axi_bypass_req_o.aw.size  = 3'(amo_req_q.size);
        axi_bypass_req_o.aw.atop  = 6'(amo_req_q.amo_op); // memory performs it
        axi_bypass_req_o.aw.burst = 2'b01;
        if (axi_bypass_rsp_i.aw_ready) state_d = AMO_W;
      end

      AMO_W: begin
        axi_bypass_req_o.w_valid = 1'b1;
        axi_bypass_req_o.w.data  = amo_req_q.operand_b;
        axi_bypass_req_o.w.strb  = amo_strb;
        axi_bypass_req_o.w.last  = 1'b1;
        if (axi_bypass_rsp_i.w_ready) begin
          got_b_d = 1'b0;
          got_r_d = 1'b0;
          state_d = AMO_WAIT;
        end
      end

      AMO_WAIT: begin
        axi_bypass_req_o.b_ready = 1'b1;
        axi_bypass_req_o.r_ready = 1'b1;
        if (axi_bypass_rsp_i.b_valid) got_b_d = 1'b1;
        if (axi_bypass_rsp_i.r_valid) begin
          got_r_d      = 1'b1;
          amo_result_d = axi_bypass_rsp_i.r.data; // pre-operation value
        end
        if ((got_b_q || axi_bypass_rsp_i.b_valid) &&
            (got_r_q || axi_bypass_rsp_i.r_valid))
          state_d = AMO_DONE;
      end

      AMO_DONE: begin
        amo_ack_d = 1'b1;
        got_b_d   = 1'b0;
        got_r_d   = 1'b0;
        state_d   = IDLE;
      end

      default: state_d = IDLE;
    endcase
  end

  // ---------------------------------------------------------------------------
  // state: asynchronous assert, and reset discards rather than drains (A5)
  // ---------------------------------------------------------------------------
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_q          <= IDLE;
      miss_req_q       <= '0;
      bypass_req_q     <= '0;
      amo_req_q        <= '0;
      bypass_port_q    <= '0;
      mshr_valid_q     <= 1'b0;
      flush_cnt_q      <= '0;
      flush_ack_en_q   <= 1'b0;
      amo_pending_q    <= 1'b0;
      victim_way_q     <= '0;
      victim_line_q    <= '0;
      line_q           <= '0;
      beat_cnt_q       <= '0;
      got_b_q          <= 1'b0;
      got_r_q          <= 1'b0;
      amo_result_q     <= '0;
      flush_ack_q      <= 1'b0;
      miss_pulse_q     <= 1'b0;
      amo_ack_q        <= 1'b0;
      bypass_valid_q   <= '0;
      bypass_data_q    <= '0;
      active_serving_q <= '0;
    end else begin
      state_q          <= state_d;
      miss_req_q       <= miss_req_d;
      bypass_req_q     <= bypass_req_d;
      amo_req_q        <= amo_req_d;
      bypass_port_q    <= bypass_port_d;
      mshr_valid_q     <= mshr_valid_d;
      flush_cnt_q      <= flush_cnt_d;
      flush_ack_en_q   <= flush_ack_en_d;
      amo_pending_q    <= amo_pending_d;
      victim_way_q     <= victim_way_d;
      victim_line_q    <= victim_line_d;
      line_q           <= line_d;
      beat_cnt_q       <= beat_cnt_d;
      got_b_q          <= got_b_d;
      got_r_q          <= got_r_d;
      amo_result_q     <= amo_result_d;
      flush_ack_q      <= flush_ack_d;
      miss_pulse_q     <= miss_pulse_d;
      amo_ack_q        <= amo_ack_d;
      bypass_valid_q   <= bypass_valid_d;
